/* ------------------------------------------------------------------ helpers */

static bool str_same(Str a, Str b) {
    return a.len == b.len && (a.len == 0 || memcmp(a.p, b.p, (size_t)a.len) == 0);
}

static bool user_equal(const UrlUserinfo *a, const UrlUserinfo *b) {
    if (a == NULL || b == NULL)
        return a == b;
    return str_same(a->username, b->username) && str_same(a->password, b->password) &&
           a->password_set == b->password_set;
}

/* reflect.DeepEqual on two URLs, which the mem and size fields stay out of. */
static bool url_equal(const Url *a, const Url *b) {
    if (a == NULL || b == NULL)
        return a == b;
    return str_same(a->scheme, b->scheme) && str_same(a->opaque, b->opaque) &&
           user_equal(a->user, b->user) && str_same(a->host, b->host) &&
           str_same(a->path, b->path) && str_same(a->fragment, b->fragment) &&
           str_same(a->raw_query, b->raw_query) && str_same(a->raw_path, b->raw_path) &&
           str_same(a->raw_fragment, b->raw_fragment) &&
           a->force_query == b->force_query && a->omit_host == b->omit_host;
}

/* Go's ufmt, for the messages. */
static Str ufmt(Alloc *a, const Url *u) {
    if (u == NULL)
        return S("<nil>");
    Str user = S("<nil>");
    if (u->user != NULL) {
        bool ok;
        Str pass = url_userinfo_password(u->user, &ok);
        user =
            ok ? fmt_sprintf_v(a, "%s:%s", u->user->username, pass) : u->user->username;
    }
    return fmt_sprintf_v(a,
                         "opaque=%q, scheme=%q, user=%#v, pass=%#v, host=%q, path=%q, "
                         "rawpath=%q, rawq=%q, frag=%q, rawfrag=%q, forcequery=%v, "
                         "omithost=%t",
                         u->opaque, u->scheme, user, user, u->host, u->path,
                         u->raw_path, u->raw_query, u->fragment, u->raw_fragment,
                         u->force_query, u->omit_host);
}

static const Str no_values[1];

/* Values from a spec: NULL is a nil map and "" an empty one, and otherwise
 * each line is "k=v" to add v under k, "k" for k with a nil slice, or "k!" for
 * k with an empty one. */
static UrlValues values_from(Alloc *a, const char *spec) {
    if (spec == NULL)
        return NULL;
    UrlValues v = url_values_make(a);
    const char *p = spec;
    while (*p != '\0') {
        const char *end = strchr(p, '\n');
        if (end == NULL)
            end = p + strlen(p);
        const char *eq = memchr(p, '=', (size_t)(end - p));
        if (eq != NULL) {
            url_values_add(v, str_from_bytes(p, (Int)(eq - p)),
                           str_from_bytes(eq + 1, (Int)(end - eq - 1)));
        } else if (end > p && end[-1] == '!') {
            Str k = str_from_bytes(p, (Int)(end - p - 1));
            Slice s = slice_from((void *)(uintptr_t)no_values, 0, 0, TYPE_STRING);
            map_set(v, &k, &s);
        } else {
            Str k = str_from_bytes(p, (Int)(end - p));
            Slice s = slice_from(NULL, 0, 0, TYPE_STRING);
            map_set(v, &k, &s);
        }
        p = *end == '\n' ? end + 1 : end;
    }
    return v;
}

/* reflect.DeepEqual on two Values, where nil and empty are not the same, for
 * the map and for each slice in it. */
static bool values_equal(UrlValues a, UrlValues b) {
    if (a == NULL || b == NULL)
        return a == b;
    if (map_len(a) != map_len(b))
        return false;
    const void *k;
    void *val;
    for (MapIter it = map_iter(a); map_next(&it, &k, &val);) {
        const Slice *x = (const Slice *)val;
        const Slice *y = (const Slice *)map_get(b, k);
        if (y == NULL || (x->p == NULL) != (y->p == NULL) || x->len != y->len)
            return false;
        for (Int i = 0; i < x->len; i++)
            if (!str_same(((const Str *)x->p)[i], ((const Str *)y->p)[i]))
                return false;
    }
    return true;
}

static bool str_has(Str s, const char *sub) {
    size_t n = strlen(sub);
    for (Int i = 0; i + (Int)n <= s.len; i++)
        if (memcmp(s.p + i, sub, n) == 0)
            return true;
    return false;
}

#define ARENA_BEGIN                                                                    \
    Arena ar;                                                                          \
    arena_init(&ar, NULL, 0);                                                          \
    Alloc *a = arena_allocator(&ar)
#define ARENA_END arena_free(&ar)

/* -------------------------------------------------------------------- tests */

static void TestParse(TestingT *t) {
    ARENA_BEGIN;
    for (size_t i = 0; i < sizeof urltests / sizeof urltests[0]; i++) {
        const URLTest *tt = &urltests[i];
        if (tt->in.len == 0)
            continue;
        Error err;
        Url *u = url_parse(a, tt->in, &err);
        if (BURROW_FAILED(err)) {
            testing_t_errorf_v(t, "Parse(%q) returned error %s", tt->in,
                               error_text(err));
            continue;
        }
        if (!url_equal(u, tt->out))
            testing_t_errorf_v(t, "Parse(%q):\n\tgot  %s\n\twant %s\n", tt->in,
                               ufmt(a, u), ufmt(a, tt->out));
        url_free(a, u);
    }
    ARENA_END;
}

static const Str path_that_looks_scheme_relative =
    SI("//not.a.user@not.a.host/just/a/path");

static void TestParseRequestURI(TestingT *t) {
    ARENA_BEGIN;
    for (size_t i = 0; i < sizeof parseRequestURLTests / sizeof parseRequestURLTests[0];
         i++) {
        const ParseRequestURLTestsCase *test = &parseRequestURLTests[i];
        Error err;
        (void)url_parse_request_uri(a, test->url, &err);
        if (test->expectedValid && BURROW_FAILED(err))
            testing_t_errorf_v(t, "ParseRequestURI(%q) gave err %s; want no error",
                               test->url, error_text(err));
        else if (!test->expectedValid && BURROW_OK(err))
            testing_t_errorf_v(t, "ParseRequestURI(%q) gave nil error; want some error",
                               test->url);
    }
    Error err;
    Url *u = url_parse_request_uri(a, path_that_looks_scheme_relative, &err);
    if (BURROW_FAILED(err)) {
        testing_t_fatalf_v(t, "Unexpected error %s", error_text(err));
        ARENA_END;
        return;
    }
    if (!str_same(u->path, path_that_looks_scheme_relative))
        testing_t_errorf_v(t, "ParseRequestURI path:\ngot  %q\nwant %q", u->path,
                           path_that_looks_scheme_relative);
    ARENA_END;
}

static void TestURLString(TestingT *t) {
    ARENA_BEGIN;
    for (size_t i = 0; i < sizeof urltests / sizeof urltests[0]; i++) {
        const URLTest *tt = &urltests[i];
        const Url *u = tt->out;
        if (tt->in.len != 0) {
            Error err;
            u = url_parse(a, tt->in, &err);
            if (BURROW_FAILED(err)) {
                testing_t_errorf_v(t, "Parse(%q) returned error %s", tt->in,
                                   error_text(err));
                continue;
            }
        }
        Str expected = tt->roundtrip.len != 0 ? tt->roundtrip : tt->in;
        Str s = url_string(u, a);
        if (!str_same(s, expected))
            testing_t_errorf_v(t, "Parse(%q).String() == %q (expected %q)", tt->in, s,
                               expected);
    }
    for (size_t i = 0; i < sizeof stringURLTests / sizeof stringURLTests[0]; i++) {
        const StringURLTestsCase *tt = &stringURLTests[i];
        Str got = url_string(&tt->url, a);
        if (!str_same(got, tt->want))
            testing_t_errorf_v(t, "%s.String() = %q; want %q", ufmt(a, &tt->url), got,
                               tt->want);
    }
    ARENA_END;
}

