/* Whether err is an EscapeError with the text want, or no error for NULL. */
static bool escape_err_is(Error err, const char *want) {
    if (want == NULL)
        return BURROW_OK(err);
    const Str *e = (const Str *)errors_as(err, TYPE_URL_ESCAPE_ERROR);
    if (e == NULL)
        return false;
    return str_same(*e, str_from_cstr(want));
}

static Str replace_all(Alloc *a, Str s, const char *old, const char *new_) {
    return strings_replace_all(a, s, str_from_cstr(old), str_from_cstr(new_));
}

static void TestUnescape(TestingT *t) {
    ARENA_BEGIN;
    for (size_t i = 0; i < sizeof unescapeTests / sizeof unescapeTests[0]; i++) {
        const EscapeTest *tt = &unescapeTests[i];
        Error err;
        Str actual = url_query_unescape(a, tt->in, &err);
        if (!str_same(actual, tt->out) || !escape_err_is(err, tt->err))
            testing_t_errorf_v(t, "QueryUnescape(%q) = %q, %s; want %q, %s", tt->in,
                               actual, error_text(err), tt->out,
                               tt->err ? tt->err : "<nil>");
        Str in = tt->in;
        Str out = tt->out;
        if (str_has(tt->in, "+")) {
            in = replace_all(a, tt->in, "+", "%20");
            actual = url_path_unescape(a, in, &err);
            if (!str_same(actual, tt->out) || !escape_err_is(err, tt->err))
                testing_t_errorf_v(t, "PathUnescape(%q) = %q, %s; want %q, %s", in,
                                   actual, error_text(err), tt->out,
                                   tt->err ? tt->err : "<nil>");
            if (tt->err == NULL) {
                Str s = url_query_unescape(a, replace_all(a, tt->in, "+", "XXX"), &err);
                if (BURROW_FAILED(err))
                    continue;
                in = tt->in;
                out = replace_all(a, s, "XXX", "+");
            }
        }
        actual = url_path_unescape(a, in, &err);
        if (!str_same(actual, out) || !escape_err_is(err, tt->err))
            testing_t_errorf_v(t, "PathUnescape(%q) = %q, %s; want %q, %s", in, actual,
                               error_text(err), out, tt->err ? tt->err : "<nil>");
    }
    ARENA_END;
}

