static void TestResolveReference(TestingT *t) {
    ARENA_BEGIN;
    const Url opaque = {.scheme = SI("scheme"), .opaque = SI("opaque")};
    for (size_t i = 0;
         i < sizeof resolveReferenceTests / sizeof resolveReferenceTests[0]; i++) {
        const ResolveReferenceTestsCase *test = &resolveReferenceTests[i];
        Error err;
        Url *base = url_parse(a, test->base, &err);
        if (BURROW_FAILED(err)) {
            testing_t_fatalf_v(t, "Parse(%q) got err %s", test->base, error_text(err));
            break;
        }
        Url *rel = url_parse(a, test->rel, &err);
        if (BURROW_FAILED(err)) {
            testing_t_fatalf_v(t, "Parse(%q) got err %s", test->rel, error_text(err));
            break;
        }
        Url *url = url_resolve_reference(base, a, rel);
        Str got = url_string(url, a);
        if (!str_same(got, test->expected))
            testing_t_errorf_v(t, "URL(%q).ResolveReference(%q)\ngot  %q\nwant %q",
                               test->base, test->rel, got, test->expected);
        if (base == url)
            testing_t_errorf_v(
                t, "Expected URL.ResolveReference to return new URL instance.");
        url = url_parse_ref(base, a, test->rel, &err);
        if (BURROW_FAILED(err)) {
            testing_t_errorf_v(t, "URL(%q).Parse(%q) failed: %s", test->base, test->rel,
                               error_text(err));
        } else if (!str_same(got = url_string(url, a), test->expected)) {
            testing_t_errorf_v(t, "URL(%q).Parse(%q)\ngot  %q\nwant %q", test->base,
                               test->rel, got, test->expected);
        } else if (base == url) {
            testing_t_errorf_v(t, "Expected URL.Parse to return new URL instance.");
        }
        url = url_resolve_reference(base, a, &opaque);
        if (!url_equal(url, &opaque))
            testing_t_errorf_v(
                t, "ResolveReference failed to resolve opaque URL:\ngot  %s\nwant %s",
                ufmt(a, url), ufmt(a, &opaque));
        url = url_parse_ref(base, a, S("scheme:opaque"), &err);
        if (BURROW_FAILED(err))
            testing_t_errorf_v(t, "URL(%q).Parse(\"scheme:opaque\") failed: %s",
                               test->base, error_text(err));
        else if (!url_equal(url, &opaque))
            testing_t_errorf_v(t,
                               "Parse failed to resolve opaque URL:\ngot  %s\nwant %s",
                               ufmt(a, &opaque), ufmt(a, url));
        else if (base == url)
            testing_t_errorf_v(t, "Expected URL.Parse to return new URL instance.");
    }
    ARENA_END;
}

static void TestQueryValues(TestingT *t) {
    ARENA_BEGIN;
    Url *u = url_parse(a, S("http://x.com?foo=bar&bar=1&bar=2&baz"), NULL);
    UrlValues v = url_query(u, a);
    if (map_len(v) != 3)
        testing_t_errorf_v(t, "got %d keys in Query values, want 3", map_len(v));
    Str g;
    if (!str_same(g = url_values_get(v, S("foo")), S("bar")))
        testing_t_errorf_v(t, "Get(foo) = %q, want %q", g, S("bar"));
    if (!str_same(g = url_values_get(v, S("Foo")), S("")))
        testing_t_errorf_v(t, "Get(Foo) = %q, want %q", g, S(""));
    if (!str_same(g = url_values_get(v, S("bar")), S("1")))
        testing_t_errorf_v(t, "Get(bar) = %q, want %q", g, S("1"));
    if (!str_same(g = url_values_get(v, S("baz")), S("")))
        testing_t_errorf_v(t, "Get(baz) = %q, want %q", g, S(""));
    CHECK(url_values_has(v, S("foo")));
    CHECK(url_values_has(v, S("bar")));
    CHECK(url_values_has(v, S("baz")));
    CHECK(!url_values_has(v, S("noexist")));
    url_values_del(v, S("bar"));
    if (!str_same(g = url_values_get(v, S("bar")), S("")))
        testing_t_errorf_v(t, "second Get(bar) = %q, want %q", g, S(""));
    ARENA_END;
}

static void TestParseQuery(TestingT *t) {
    ARENA_BEGIN;
    for (size_t i = 0; i < sizeof parseTests / sizeof parseTests[0]; i++) {
        const ParseTest *test = &parseTests[i];
        Error err;
        UrlValues form = url_parse_query(a, test->query, &err);
        if (test->ok != BURROW_OK(err))
            testing_t_errorf_v(t, "%q: Unexpected error: %s, want %s", test->query,
                               error_text(err), test->ok ? "<nil>" : "<error>");
        UrlValues want = values_from(a, test->out);
        if (map_len(form) != map_len(want))
            testing_t_errorf_v(t, "%q: len(form) = %d, want %d", test->query,
                               map_len(form), map_len(want));
        const void *k;
        void *val;
        for (MapIter it = map_iter(want); map_next(&it, &k, &val);) {
            const Slice *evs = (const Slice *)val;
            const Slice *vs = (const Slice *)map_get(form, k);
            if (vs == NULL) {
                testing_t_errorf_v(t, "%q: Missing key %q", test->query,
                                   *(const Str *)k);
                continue;
            }
            if (vs->len != evs->len) {
                testing_t_errorf_v(t, "%q: len(form[%q]) = %d, want %d", test->query,
                                   *(const Str *)k, vs->len, evs->len);
                continue;
            }
            for (Int j = 0; j < evs->len; j++) {
                Str v = ((const Str *)vs->p)[j], ev = ((const Str *)evs->p)[j];
                if (!str_same(v, ev))
                    testing_t_errorf_v(t, "%q: form[%q][%d] = %q, want %q", test->query,
                                       *(const Str *)k, j, v, ev);
            }
        }
    }
    ARENA_END;
}

static void TestParseQueryLimits(TestingT *t) {
    static const struct {
        Int params;
        const char *godebug;
        bool want_err;
    } tests[] = {
        {10, "", false},
        {10000, "", false},
        {10001, "", true},
        {10, "urlmaxqueryparams=9", true},
        {10001, "urlmaxqueryparams=0", false},
    };
    ARENA_BEGIN;
    for (size_t i = 0; i < sizeof tests / sizeof tests[0]; i++) {
        burrow__url_godebug_set(tests[i].godebug);
        Int n = tests[i].params;
        /* "p0&p1&...", counted and then written. */
        Int size = 0;
        for (Int j = 0; j < n; j++)
            size += (j > 0) + 1 + (Int)snprintf(NULL, 0, "%lld", (long long)j);
        char *q = (char *)mem_alloc_nozero(a, (size_t)size + 1, 1);
        Int w = 0;
        for (Int j = 0; j < n; j++)
            w += (Int)snprintf(q + w, (size_t)(size + 1 - w), "%sp%lld",
                               j > 0 ? "&" : "", (long long)j);
        Error err;
        UrlValues got = url_parse_query(a, str_from_bytes(q, w), &err);
        if (BURROW_FAILED(err) != tests[i].want_err)
            testing_t_errorf_v(t,
                               "GODEBUG=%s ParseQuery(%d params) = %s, want error: %t",
                               tests[i].godebug, n, error_text(err), tests[i].want_err);
        if (BURROW_FAILED(err))
            continue;
        if (map_len(got) != n)
            testing_t_errorf_v(
                t, "GODEBUG=%s ParseQuery(%d params): got %d params, want %d",
                tests[i].godebug, n, map_len(got), n);
    }
    burrow__url_godebug_set(NULL);
    ARENA_END;
}

