/* Go's timeoutError, temporaryError and timeoutTemporaryError. */

#define TIMEOUT_ERROR_FIELDS(F, T) F(T, bool, timeout, "")
BURROW_STRUCT_DECL(TimeoutError, TIMEOUT_ERROR_FIELDS);

static Str timeout_error_error(TimeoutError *e) {
    (void)e;
    return S("timeout error");
}

static bool timeout_error_timeout(TimeoutError *e) {
    return e->timeout;
}

#define TE_SIG_Error(IN, OUT) OUT(Str)
#define TE_SIG_Bool(IN, OUT) OUT(bool)
#define TIMEOUT_ERROR_METHODS(M, T)                                                    \
    M(T, Error, timeout_error_error, TE_SIG_Error)                                     \
    M(T, Timeout, timeout_error_timeout, TE_SIG_Bool)
BURROW_STRUCT_DEFINE_METHODS(TimeoutError, TIMEOUT_ERROR_FIELDS, TIMEOUT_ERROR_METHODS);

#define TEMPORARY_ERROR_FIELDS(F, T) F(T, bool, temporary, "")
BURROW_STRUCT_DECL(TemporaryError, TEMPORARY_ERROR_FIELDS);

static Str temporary_error_error(TemporaryError *e) {
    (void)e;
    return S("temporary error");
}

static bool temporary_error_temporary(TemporaryError *e) {
    return e->temporary;
}

#define TEMPORARY_ERROR_METHODS(M, T)                                                  \
    M(T, Error, temporary_error_error, TE_SIG_Error)                                   \
    M(T, Temporary, temporary_error_temporary, TE_SIG_Bool)
BURROW_STRUCT_DEFINE_METHODS(TemporaryError, TEMPORARY_ERROR_FIELDS,
                             TEMPORARY_ERROR_METHODS);

#define BOTH_ERROR_FIELDS(F, T)                                                        \
    F(T, bool, timeout, "")                                                            \
    F(T, bool, temporary, "")
BURROW_STRUCT_DECL(TimeoutTemporaryError, BOTH_ERROR_FIELDS);

static Str both_error_error(TimeoutTemporaryError *e) {
    (void)e;
    return S("timeout/temporary error");
}

static bool both_error_temporary(TimeoutTemporaryError *e) {
    return e->temporary;
}

static bool both_error_timeout(TimeoutTemporaryError *e) {
    return e->timeout;
}

#define BOTH_ERROR_METHODS(M, T)                                                       \
    M(T, Error, both_error_error, TE_SIG_Error)                                        \
    M(T, Temporary, both_error_temporary, TE_SIG_Bool)                                 \
    M(T, Timeout, both_error_timeout, TE_SIG_Bool)
BURROW_STRUCT_DEFINE_METHODS(TimeoutTemporaryError, BOTH_ERROR_FIELDS,
                             BOTH_ERROR_METHODS);

static Str timeout_vt_message(const void *self) {
    (void)self;
    return S("timeout error");
}

static const ErrorVT timeout_vt = {.self_type = &burrow_type_TimeoutError,
                                   .message = timeout_vt_message};
static const ErrorVT temporary_vt = {.self_type = &burrow_type_TemporaryError,
                                     .message = timeout_vt_message};
static const ErrorVT both_vt = {.self_type = &burrow_type_TimeoutTemporaryError,
                                .message = timeout_vt_message};

static void TestURLErrorImplementsNetError(TestingT *t) {
    for (size_t i = 0; i < sizeof netErrorTests / sizeof netErrorTests[0]; i++) {
        const NetErrorTestsCase *tt = &netErrorTests[i];
        TimeoutError te = {tt->timeout_field};
        TemporaryError pe = {tt->temporary_field};
        TimeoutTemporaryError be = {tt->timeout_field, tt->temporary_field};
        Error inner = io_eof;
        switch (tt->kind) {
        case NET_TIMEOUT:
            inner = (Error){&timeout_vt, &te};
            break;
        case NET_TEMPORARY:
            inner = (Error){&temporary_vt, &pe};
            break;
        case NET_BOTH:
            inner = (Error){&both_vt, &be};
            break;
        default:
            break;
        }
        UrlError e = {SI("Get"), SI("http://google.com/"), inner};
        if (url_error_timeout(&e) != tt->timeout) {
            testing_t_errorf_v(t, "%d: err.Timeout(): got %t, want %t", (Int)i + 1,
                               url_error_timeout(&e), tt->timeout);
            continue;
        }
        if (url_error_temporary(&e) != tt->temporary)
            testing_t_errorf_v(t, "%d: err.Temporary(): got %t, want %t", (Int)i + 1,
                               url_error_temporary(&e), tt->temporary);
    }
}

