/* Go's TestJSON and TestGob go through encoding/json and encoding/gob, which
 * are not ported yet. What they test is the MarshalBinary and UnmarshalBinary
 * round trip, which this does directly. */
static void TestMarshalBinary(TestingT *t) {
    ARENA_BEGIN;
    Error err;
    Url *u = url_parse(a, S("https://www.google.com/x?y=z"), &err);
    if (BURROW_FAILED(err)) {
        testing_t_fatalf_v(t, "%s", error_text(err));
        ARENA_END;
        return;
    }
    Slice b = url_marshal_binary(u, a, &err);
    CHECK(BURROW_OK(err));
    Url u1 = {.scheme = {0}};
    err = url_unmarshal_binary(&u1, a, b);
    CHECK(BURROW_OK(err));
    Str got = url_string(&u1, a), want = url_string(u, a);
    if (!str_same(got, want))
        testing_t_errorf_v(t, "decoded to: %s\nwant: %s\n", got, want);
    Slice c =
        url_append_binary(u, a, slice_append(a, slice_nil(TYPE_BYTE), "x:", 2), &err);
    CHECK(BURROW_OK(err));
    CHECK(str_same(str_from_bytes(c.p, c.len), S("x:https://www.google.com/x?y=z")));

    /* The same through the type's methods, which is how encoding finds them. */
    const Method *m = type_method_by_name(TYPE_URL, S("String"));
    CHECK(m != NULL);
    if (m != NULL) {
        Str s;
        void *rets[1] = {&s};
        method_call(m, u, NULL, rets);
        CHECK(str_same(s, want));
    }
    ARENA_END;
}

