static void TestJoinPath(TestingT *t) {
    ARENA_BEGIN;
    for (size_t i = 0; i < sizeof join_path_tests / sizeof join_path_tests[0]; i++) {
        const JoinPathTestsCase *tt = &join_path_tests[i];
        Slice elem = slice_from((void *)(uintptr_t)tt->elem, tt->elem_len, tt->elem_len,
                                TYPE_STRING);
        Error err;
        Str out = url_join_path_str(a, tt->base, elem, &err);
        if (!str_same(out, tt->out) || BURROW_OK(err) != (tt->out.len != 0))
            testing_t_errorf_v(t, "JoinPath(%q, %d elems) = %q, %s, want %q, %s",
                               tt->base, tt->elem_len, out, error_text(err), tt->out,
                               tt->out.len == 0 ? "non-nil error" : "nil");
        Url *u = url_parse(a, tt->base, &err);
        if (BURROW_FAILED(err)) {
            if (tt->out.len != 0)
                testing_t_errorf_v(t, "Parse(%q) = %s", tt->base, error_text(err));
            continue;
        }
        Str want = tt->out.len == 0 ? tt->base : tt->out;
        out = url_string(url_join_path(u, a, elem), a);
        if (!str_same(out, want))
            testing_t_errorf_v(t, "Parse(%q).JoinPath(%d elems) = %q, want %q",
                               tt->base, tt->elem_len, out, want);
    }
    /* The variadic form is the same thing. */
    Url *u = url_parse(a, S("https://go.googlesource.com/a"), NULL);
    Str got = url_string(url_join_path_v(u, a, 3, S("b"), S("../c"), S("d/")), a);
    CHECK(str_same(got, S("https://go.googlesource.com/a/c/d/")));
    ARENA_END;
}

