static void TestURLClone(TestingT *t) {
    ARENA_BEGIN;
    for (size_t i = 0; i < sizeof url_clone_tests / sizeof url_clone_tests[0]; i++) {
        const UrlCloneTestsCase *tt = &url_clone_tests[i];
        Url *cloned = url_clone(tt->in, a);
        if (!url_equal(tt->in, cloned)) {
            testing_t_errorf_v(t, "%s: Differing values\n%s\n%s", tt->name,
                               ufmt(a, tt->in), ufmt(a, cloned));
            continue;
        }
        if (tt->in == NULL)
            continue;
        if (tt->in == cloned) {
            testing_t_errorf_v(t, "%s: URL: same pointer returned", tt->name);
            continue;
        }
        cloned->scheme = S("https");
        if (str_same(cloned->scheme, tt->in->scheme))
            testing_t_errorf_v(t,
                               "%s: Inconsistent state: cloned.scheme changed and "
                               "reflected in the input's scheme",
                               tt->name);
        if (url_equal(tt->in, cloned))
            testing_t_errorf_v(
                t,
                "%s: Inconsistent state: cloned and input are somehow the "
                "same",
                tt->name);
        if (!user_equal(tt->in->user, cloned->user))
            testing_t_errorf_v(t, "%s: Differing .User", tt->name);
        if (tt->in->user != NULL && tt->in->user == cloned->user)
            testing_t_errorf_v(t, "%s: .User: same pointer returned", tt->name);
        url_free(a, cloned);
    }
    ARENA_END;
}

static void TestValuesClone(TestingT *t) {
    ARENA_BEGIN;
    for (size_t i = 0; i < sizeof values_clone_tests / sizeof values_clone_tests[0];
         i++) {
        const ValuesCloneTestsCase *tt = &values_clone_tests[i];
        Str name = tt->name;
        UrlValues in = values_from(a, tt->in);
        UrlValues cloned1 = url_values_clone(in, a);
        if (!values_equal(in, cloned1)) {
            testing_t_errorf_v(t, "%s: reflect.DeepEqual failed", name);
            continue;
        }
        if (cloned1 == NULL && in == NULL)
            continue;
        Str ab[2] = {SI("a"), SI("b")};
        Str xk = S("XXXXXXXXXXX");
        Slice abs = slice_from(ab, 2, 2, TYPE_STRING);
        map_set(cloned1, &xk, &abs);
        if (values_equal(in, cloned1)) {
            testing_t_errorf_v(
                t,
                "%s: Inconsistent state: cloned and input are somehow the "
                "same",
                name);
            continue;
        }
        UrlValues cloned2 = url_values_clone(in, a);
        url_values_add(cloned2, S("a"), S("A"));
        if (!url_values_has(cloned2, S("a")))
            testing_t_errorf_v(t, "%s: Cloned doesn't have the desired key: a", name);
        if (values_equal(in, cloned2)) {
            testing_t_errorf_v(t,
                               "%s: reflect.DeepEqual unexpectedly passed after modify "
                               "cloned",
                               name);
            continue;
        }
        url_values_del(cloned2, S("a"));
        if (!values_equal(in, cloned2)) {
            testing_t_errorf_v(t, "%s: reflect.DeepEqual failed", name);
            continue;
        }
        UrlValues cloned3 = url_values_clone(in, a);
        if (map_len(cloned3) == 0)
            continue;
        const void *k0;
        MapIter it = map_iter(cloned3);
        (void)map_next(&it, &k0, NULL);
        Str key0 = *(const Str *)k0;
        Slice *vs = (Slice *)map_get(cloned3, &key0);
        if (vs->len == 0) {
            Str golang = S("golang");
            *vs = slice_append(a, *vs, &golang, 1);
        } else {
            ((Str *)vs->p)[0] = S("directly modified");
            Str g = url_values_get(cloned3, key0);
            if (!str_same(g, S("directly modified")))
                testing_t_errorf_v(t, "%s: Get failed:\n\tGot:  %q\n\tWant: %q", name,
                                   g, S("directly modified"));
        }
        if (values_equal(in, cloned3)) {
            testing_t_errorf_v(t,
                               "%s: reflect.DeepEqual unexpectedly passed after modify "
                               "cloned",
                               name);
            continue;
        }
        UrlValues cloned4 = url_values_clone(in, a);
        url_values_set(cloned4, key0, S("good night"));
        if (values_equal(in, cloned4))
            testing_t_errorf_v(t,
                               "%s: reflect.DeepEqual unexpectedly passed after modify "
                               "cloned",
                               name);
        Str g = url_values_get(cloned4, key0);
        if (!str_same(g, S("good night")))
            testing_t_errorf_v(t, "%s: Get failed:\n\tGot:  %q\n\tWant: %q", name, g,
                               S("good night"));
    }
    ARENA_END;
}

/* Not in Go's tests: the error types and their texts. */
static void TestErrorTexts(TestingT *t) {
    ARENA_BEGIN;
    Error err;
    (void)url_parse(a, S("http://[::1]:namedport"), &err);
    CHECK(str_same(
        error_text(err),
        S("parse \"http://[::1]:namedport\": invalid port \":namedport\" after host")));
    const UrlError *ue = (const UrlError *)errors_as(err, TYPE_URL_ERROR);
    CHECK(ue != NULL);
    if (ue != NULL) {
        CHECK(str_same(ue->op, S("parse")));
        CHECK(str_same(ue->url, S("http://[::1]:namedport")));
        CHECK(str_same(url_error_error(ue, a), error_text(err)));
    }

    (void)url_parse(a, S("http://a b.com/#frag"), &err);
    CHECK(
        str_same(error_text(err),
                 S("parse \"http://a b.com/\": invalid character \" \" in host name")));
    const Str *he = (const Str *)errors_as(err, TYPE_URL_INVALID_HOST_ERROR);
    CHECK(he != NULL);
    if (he != NULL)
        CHECK(str_same(*he, S(" ")));

    (void)url_parse(a, S("http://x/%zz#%yy"), &err);
    CHECK(str_same(error_text(err),
                   S("parse \"http://x/%zz\": invalid URL escape \"%zz\"")));
    (void)url_parse(a, S("http://x/#%yy"), &err);
    CHECK(str_same(error_text(err),
                   S("parse \"http://x/#%yy\": invalid URL escape \"%yy\"")));

    CHECK(str_same(url_escape_error_error(S("%4"), a), S("invalid URL escape \"%4\"")));
    CHECK(str_same(url_invalid_host_error_error(S("<"), a),
                   S("invalid character \"<\" in host name")));
    Error e1 = url_escape_error_as_error(S("%4"), a);
    Error e2 = url_escape_error_as_error(S("%4"), a);
    CHECK(errors_is(e1, e2));
    CHECK(!errors_is(e1, url_invalid_host_error_as_error(S("%4"), a)));

    (void)url_parse(a, S(":foo"), &err);
    CHECK(str_same(error_text(err), S("parse \":foo\": missing protocol scheme")));
    (void)url_parse_request_uri(a, S(""), &err);
    CHECK(str_same(error_text(err), S("parse \"\": empty url")));
    (void)url_parse(a, S("http://[fe80::1%en0]/"), &err);
    CHECK(str_same(error_text(err),
                   S("parse \"http://[fe80::1%en0]/\": invalid URL escape \"%en\"")));
    (void)url_parse(a, S("http://[192.168.0.1]/"), &err);
    CHECK(str_same(error_text(err),
                   S("parse \"http://[192.168.0.1]/\": invalid IP-literal")));
    ARENA_END;
}

/* A Url from url_parse is one block, so url_free under a checking allocator
 * has to give back exactly what was taken, on success and on failure. */
static void TestParseFree(TestingT *t) {
    static const char *const ins[] = {
        "http://user:p%40ss@[fe80::1%25en0]:8080/a%20b/c?q=1#f%20g",
        "mailto:x@y",
        "http://[::1]:bad",
        "http://x/%zz",
        "",
        "*",
    };
    Track tr;
    track_init(&tr, heap_allocator());
    Alloc *a = track_allocator(&tr);
    for (size_t i = 0; i < sizeof ins / sizeof ins[0]; i++) {
        Error err;
        Url *u = url_parse(a, str_from_cstr(ins[i]), &err);
        if (u != NULL) {
            Url *c = url_clone(u, a);
            CHECK(url_equal(u, c));
            url_free(a, c);
            Url *r = url_resolve_reference(u, a, &(const Url){.path = SI("../x y")});
            url_free(a, r);
            Url *j = url_join_path_v(u, a, 2, S("p q"), S(".."));
            url_free(a, j);
        }
        url_free(a, u);
    }
    CHECK(track_check(&tr) == 0);
    track_free(&tr);
}

